target("rttnano")
    set_kind("object")
    set_default(false)

    on_load(function(target)
        local conf = target:data("kconfig")
        if not conf.THIRD_RTOS_RTTNANO then
            return
        end

        import("xhive.base")
        import("xhive.proc")
        local sdir = os.scriptdir()
        local custom_port = conf.CPU_RISCV and conf.RTTNANO_RISCV_PORT_CUSTOM
        local srcs = {}
        local incs = {}
        target:add("includedirs", path.join(sdir, "include"), {public=true})
        if not custom_port then
            table.insert(srcs, path.join(sdir, "port", "*.c"))
            target:add("includedirs", path.join(sdir, "port"), {public=true})
        end

        -- components
        if conf.RT_USING_FINSH then
            local finsh_dir = path.join(sdir, "components", "finsh")
            target:add("includedirs", finsh_dir, {public=true})
            table.insert(srcs, path.join(finsh_dir, "shell.c"))
            table.insert(srcs, path.join(finsh_dir, "msh.c"))
            table.insert(srcs, path.join(finsh_dir, "msh_parse.c"))

            if conf.MSH_USING_BUILT_IN_COMMANDS then
                table.insert(srcs, path.join(finsh_dir, "cmd.c"))
            end

            if conf.DFS_USING_POSIX then
                table.insert(srcs, path.join(finsh_dir, "msh_file.c"))
            end
        end
        if conf.RT_USING_DEVICE then
            local device_dir = path.join(sdir, "components", "device")
            target:add("includedirs", device_dir, {public=true})
            table.insert(srcs, path.join(device_dir, "device.c"))
        end
        -- libcpu
        if not custom_port then
            local cpuinfo = proc.cpuinfo_by_conf(conf)
            local coredir = path.join(sdir, "libcpu", cpuinfo.arch, cpuinfo.core)
            if not os.isdir(coredir) then
                raise(vformat("arch %s core %s not support yet!", cpuinfo.arch, cpuinfo.core))
            end
            table.insert(srcs, path.join(coredir, "*_gcc.S"))
            table.insert(srcs, path.join(coredir, "*.c"))
            table.insert(incs, coredir)
            if conf.CPU_ARM then
                local common_dir = path.join(sdir, "libcpu", "arm", "common")
                -- table.insert(srcs, path.join(common_dir, "*.S"))
                table.insert(srcs, path.join(common_dir, "*.c"))
            elseif conf.CPU_RISCV then
                local common_dir = path.join(sdir, "libcpu", "risc-v", "common")
                table.insert(srcs, path.join(common_dir, "*_gcc.S"))
                table.insert(srcs, path.join(common_dir, "*.c"))
                table.insert(incs, common_dir)
            end
        end
        -- src
        table.insert(srcs, path.join(sdir, "src", "*.c"))

        -- srcs and incs
        target:add("files", srcs)
        target:add("includedirs", incs)
    end)

    before_build(function(target)
        if not target:data("kconfig").THIRD_RTOS_RTTNANO then
            return
        end

        import("core.cache.memcache")
        import("xhive.base")
        import("xhive.kconf")
        local dirs = base.load_paths()
        local sdir = os.scriptdir()

        if memcache.get("xhive", "rtconfig_built") then
            return
        end
        memcache.set("xhive", "rtconfig_built", true)

        local kconfig_entry = path.join(sdir, "Kconfig")
        local header_path   = path.join(dirs.builddir, "rtconfig.h")

        if os.exists(header_path) then
            os.rm(header_path)
        end
        kconf.build_header_with_entry(header_path, kconfig_entry)

        -- read header file, remove all "CONFIG_" prefix, add include guards, write back
        local file = io.readfile(header_path)
        file = file:gsub(" CONFIG_", " ")
        file = "// Auto Generated by xhive, do not edit!\n\n"..
               "#ifndef __RT_CONFIG_H__\n"..
               "#define __RT_CONFIG_H__\n\n"..
               file.. "\n"..
               "#endif /* __RT_CONFIG_H__ */\n"
        io.writefile(header_path, file)
    end)
